### HELPER FUNCTIONS ###########################################################
# Reuse an existing object; otherwise load it from a user-configured RDS path.
# Returns the object without overwriting an existing object in the calling environment.
load_if_missing <- function(object_name, path, envir = .GlobalEnv) {
        if (exists(object_name, envir = envir, inherits = FALSE)) {
                message("Reusing ", object_name, " from the environment.")
                return(get(object_name, envir = envir, inherits = FALSE))
        }
        if (is.null(path) || !nzchar(path) || !file.exists(path)) {
                stop("Missing ", object_name, ". Set its input RDS path in cfg: ", path)
        }
        message("Loading ", object_name, " from: ", path)
        readRDS(path)
}


# Optional exploratory plot: highlight each cluster across selected FOVs,
# with SLC17A7 molecules in the background. Call manually when needed.
plot_cluster_fovs <- function(dataset, fov_order, output_dir, clusters = unique(Idents(dataset)), molecules = 'SLC17A7', nmols = 10000, ncol = 2) {
        if (!dir.exists(output_dir)) {
                dir.create(output_dir, recursive = TRUE)
        }
        
        image_names <- names(dataset@images)
        
        for (cluster in clusters) {
                message("Processing cluster: ", cluster)
                
                # Get cell IDs for this cluster
                cluster_cells <- WhichCells(dataset, idents = cluster)
                
                # Ensure IDs are characters
                cluster_cells <- as.character(cluster_cells)
                
                plot_list <- list()
                
                for (fov in fov_order) {
                        if (!(fov %in% image_names)) {
                                message("  FOV ", fov, " not found in dataset images; skipping.")
                                next
                        }
                        
                        # Select cells that belong to this FOV/sample
                        selected_cells <- cluster_cells[startsWith(cluster_cells, paste0(fov, "_"))]
                        
                        selected_cells <- unique(selected_cells)
                        
                        if (length(selected_cells) == 0) {
                                message("  No cells found in FOV ", fov, " for cluster ", cluster, ". Adding placeholder plot.")
                                p <- ggplot() +
                                        annotate("text", x = 0.5, y = 0.5, label = paste("No cells in", fov), size = 6) +
                                        theme_void()
                        } else {
                                p <- ImageDimPlot(
                                        dataset,
                                        fov = fov,
                                        cells = selected_cells,
                                        cols = 'red',
                                        size = 2,
                                        border.size = NA,
                                        axes = FALSE,
                                        dark.background = TRUE,
                                        molecules = molecules,
                                        mols.cols = 'white',
                                        nmols = nmols,
                                        mols.alpha = 0.1,
                                        mols.size = 0.5
                                ) +
                                        DarkTheme() +
                                        ggtitle(fov) +
                                        theme(
                                                panel.grid.major = element_blank(),
                                                panel.grid.minor = element_blank()
                                        )
                        }
                        
                        plot_list[[length(plot_list) + 1]] <- p
                }
                
                pdf_file <- file.path(output_dir, paste0("cluster_", cluster, ".pdf"))
                
                if (length(plot_list) > 0) {
                        n_plots <- length(plot_list)
                        n_rows <- ceiling(n_plots / ncol)
                        pdf(pdf_file, width = 4 * ncol, height = n_rows * 4)
                        grid.arrange(grobs = plot_list, ncol = ncol)
                        dev.off()
                        message("Finished cluster ", cluster, "; saved to: ", pdf_file)
                } else {
                        message("No plots were generated for cluster ", cluster, "; no PDF created.")
                }
        }
}

### USER-EDITABLE PATHS ########################################################
# Match output_dir_data to the path used in Script 01.
# These are paths within this script, not a separate configuration file.
cfg <- list(
        datEx_rds = "path/to/directory/data/datEX_v8.rds",
        output_dir_plots = "path/to/directory/plots")

plot_dir <- file.path(cfg$output_dir_plots, "ExN_v8")

dir.create(plot_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(file.path(plot_dir, "ImageDimPlot_broad"), recursive = TRUE, showWarnings = FALSE)
dir.create(file.path(plot_dir, "ImageDimPlot_png"), recursive = TRUE, showWarnings = FALSE)

### LOAD EXN OBJECT ############################################################
# Reuse datEx if it already exists (e.g., after running Script 01).
# Otherwise, load the annotated ExN object saved by Script 01.
datEx <- load_if_missing("datEx", cfg$datEx_rds) else {
        message("Using datEx already in the environment.")
}

# Plot postmortem cells on top of epilepsy cells in group-wise UMAPs.
datEx$type <- factor(datEx$type, levels = c("epilepsy", "postmortem"))
fov_order <- c("L10", "L5", "M70", "P28", "P60", "P71", "P51", "M56",
               "B1", "F1", "H1", "I1", "J1", "L20", "D11", "D8",
               "C1", "C2", "E008", "L14", "L15", "L18", "L1", "L21",
               "L3", "D12", "D13", "E015", "L2", "D9", "D14")

# The Sample column is present in the original dataset; do not create it
# automatically from another metadata field.
if ("Sample" %in% colnames(datEx@meta.data)) {
        datEx$Sample <- factor(datEx$Sample, levels = fov_order)
}
datEx$ILAE_score <- factor(datEx$ILAE_score, levels = c("P", "0", "1", "2", "3"))
datEx$broad_subtype_ExN <- factor(datEx$broad_subtype_ExN,
                                     levels = c("GC", "MC", "CA2-3", "dCA3", "sCA1", 
                                                "dCA1", "sSub", "mSub", "dSub", "L6b"))


