### SPATIAL EXN SUBTYPE PLOTS #########################################
# Save one PDF per FOV, retaining the full sample list.
for (fov in fov_order) {
        if (!fov %in% names(datEx@images)) {
                message("Skipping missing FOV: ", fov)
                next
        }
        p <- ImageDimPlot(datEx, fov = fov, group.by = "broad_subtype_ExN",
                          size = 2, border.size = NA, axes = FALSE,
                          dark.background = FALSE, cols = pal_exN_subtype_broad) +
                theme(panel.grid.major = element_blank(),
                      panel.grid.minor = element_blank())
        ggsave(file.path(plot_dir, "ImageDimPlot_broad", paste0(fov, "_ImageDimPlot.pdf")),
               plot = p, width = 10, height = 10)
}


### EXN MARKER DOTPLOT #########################################################
