)

# Unmapped labels and missing annotations are grouped as nonExN.
meta$SingleR_grouped <- dplyr::recode(meta$SingleR_pruned_superfine,
                                      !!!recode_vector, .default = "nonExN",
                                      .missing = "nonExN")

count_table <- dplyr::count(meta, broad_subtype_ExN, SingleR_grouped, name = "n")
prop_table <- count_table %>%
        group_by(broad_subtype_ExN) %>%
        mutate(proportion = n / sum(n)) %>%
        ungroup()

prop_table$broad_subtype_ExN <- factor(prop_table$broad_subtype_ExN,
                                          levels = c("GC", "MC", "CA2-3", "dCA3", 
                                                     "sCA1", "dCA1", "sSub", "mSub", 
                                                     "dSub", "L6b"))

p_singleR <- ggplot(prop_table, aes(x = broad_subtype_ExN,
                                    y = proportion, fill = SingleR_grouped)) +
        geom_col(width = 0.8) +
        scale_fill_manual(values = pal_SingleR_grouped) +
        scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
        labs(x = "ExN cell type", y = "Proportion of SingleR labels",
             fill = "SingleR labels") +
        theme_classic(base_size = 8) +
        theme(axis.text.x = element_text(angle = 45, hjust = 1))

